function APR:StartNavigationUnlock(blockers, context)
    local data, player = self.NavigationData, Player()
    if not data or not data.CreateUnlockSession or not player or not context
        or not self:IsStepContextCurrent(context) or not blockers or #blockers == 0 then return false end
    local current = self._navigationUnlock
    if current then
        if not current.session:BeginDetour(blockers, { clock = debugprofilestop }) then return false end
        current.step, current.signature = nil, nil
    else
        -- Legacy attempts were a permanent blacklist, even when no live or
        -- saved session survived a reload. Current server conditions decide
        -- whether a detour is needed; the live session owns deduplication.
        player.NavigationUnlockAttempts = nil
        local candidates = {}
        for _, edge in ipairs(blockers) do
            local satisfied = false
            if edge.blockedRequirements and not edge.blockedActions and data.CheckRequirements then
                local character = {}
                for key, value in pairs(data.env and data.env.getCharacter and data.env.getCharacter() or {}) do
                    character[key] = value
                end
                if edge.from and edge.from.uiMapID then character.mapID = edge.from.uiMapID end
                satisfied = data:CheckRequirements(edge.blockedRequirements, character) == true
            end
            if not satisfied then candidates[#candidates + 1] = edge end
        end
        if #candidates == 0 then return false end
        local original = self.navigation.destination
        if not original then
            local step = self:GetCurrentStep()
            original = { mapID = step and step.Zone }
        end
        self._navigationUnlock = { context = context,
            session = data:CreateUnlockSession({ blockers = candidates, destination = original, clock = debugprofilestop }) }
    end
    Save(self)
    self.navigation.dirty = true
    self.navigation:RequestUpdate()
    return true
end--[[APR_DIAG]]; APR.StartNavigationUnlock = APRTrace("APR-Core/features/navigation/NavigationUnlocks.lua:43:APR:StartNavigationUnlock#6", APR.StartNavigationUnlock)--[[/APR_DIAG]]

function APR:RestoreNavigationUnlockRoute()
    local current = self._navigationUnlock
    if current then
        -- Map, arrow and UI readers call this getter frequently. Restoring is
        -- idempotent: retain the cooperative job, nested sessions and action.
        if self:IsStepContextCurrent(current.context) then return true end
        self:CancelNavigationUnlock()
        return false
    end
    local player, data = Player(), self.NavigationData
    local saved = player and player.NavigationUnlockState
    if not saved or not data or not data.RestoreUnlockSession then return false end
    local context = self:CaptureStepContext()
    if not context or context.route ~= saved.route or context.index ~= saved.index then
        player.NavigationUnlockState = nil
        return false
    end
    self._navigationUnlock = { context = context,
        session = data:RestoreUnlockSession(saved.library, { clock = debugprofilestop }) }
    return true
end--[[APR_DIAG]]; APR.RestoreNavigationUnlockRoute = APRTrace("APR-Core/features/navigation/NavigationUnlocks.lua:84:APR:RestoreNavigationUnlockRoute#7", APR.RestoreNavigationUnlockRoute)--[[/APR_DIAG]]

function APR:RefreshNavigationUnlockRoute()
