    return false
end--[[APR_DIAG]]; APR.RefreshNavigationUnlockRoute = APRTrace("APR-Core/features/navigation/NavigationUnlocks.lua:106:APR:RefreshNavigationUnlockRoute#8", APR.RefreshNavigationUnlockRoute)--[[/APR_DIAG]]
